handler.function:
console.log('[discovery] Fetching agent cards from A2A servers...');
const servers = { task_agent: 'http://localhost:3001', research_agent: 'http://localhost:3002', quality_agent: 'http://localhost:3003' };

const results = await Promise.allSettled(
  Object.entries(servers).map(async ([key, baseUrl]) => {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 30000);
    try {
      const res = await fetch(`${baseUrl}/.well-known/agent.json`, { signal: controller.signal });
      clearTimeout(timer);
      if (!res.ok) return null;
      const card = await res.json();
      return {
        name: card.name || key,
        url: baseUrl,
        skills: card.skills || [],
        description: card.description || ''
      };
    } catch {
      clearTimeout(timer);
      return null;
    }
  })
);

const availableAgents = results
  .filter(r => r.status === 'fulfilled' && r.value !== null)
  .map(r => r.value);

console.log(`[discovery] Found ${availableAgents.length} agents: ${availableAgents.map(a => a.name).join(', ')}`);
return { availableAgents };

console.log('[planner] Decomposing task and matching agents via skills...');
const lastMessage = state.messages[state.messages.length - 1];
const userTask = typeof lastMessage.content === 'string' ? lastMessage.content : JSON.stringify(lastMessage.content);

const agentsInfo = (state.availableAgents || []).map(a =>
  `- ${a.name} (${a.url})\n  desc: ${a.description}\n  skills: ${JSON.stringify(a.skills)}`
).join('\n') || '(no agents discovered - will use fallback routing)';

const planPrompt = `You are an expert in task decomposition and agent selection.
Define the team of specialists needed to accomplish the following task.

Discovered agents:
${agentsInfo}

Task: ${userTask}

Return only the following JSON array (no explanation needed):
[
  {"name": "snake_case_role_name", "role": "description of the role", "task": "specific assigned task"},
  ...
]

Constraints:
- Define between 1 and 5 workers, only as many as needed for the task
- If one person can complete the task alone, assign only one worker
- name must be in snake_case English`;

const response = await model.invoke([{ role: 'user', content: planPrompt }]);
const content = typeof response.content === 'string' ? response.content : JSON.stringify(response.content);

let workerPlans;
try {
  const jsonMatch = content.match(/\[.*\]/s);
  workerPlans = jsonMatch ? JSON.parse(jsonMatch[0]) : [];
} catch (e) {
  console.error('[planner] Failed to parse worker plans:', e);
  workerPlans = [];
}

if (!Array.isArray(workerPlans) || workerPlans.length === 0) {
  workerPlans = [{ name: 'general_worker', role: 'General handler', task: userTask }];
}

function matchAgent(task, availableAgents) {
  if (!availableAgents || availableAgents.length === 0) return null;
  const scored = availableAgents.map(agent => {
    let score = 0;
    const taskLower = task.toLowerCase();
    for (const skill of (agent.skills || [])) {
      const s = typeof skill === 'string' ? skill : JSON.stringify(skill).toLowerCase();
      if (s.includes(taskLower)) score += 2;
      for (const word of taskLower.split(/\s+/)) {
        if (word.length > 3 && s.includes(word)) score += 1;
      }
    }
    const desc = (agent.description || '').toLowerCase();
    for (const word of taskLower.split(/\s+/)) {
      if (word.length > 3 && desc.includes(word)) score += 1;
    }
    return { agent, score };
  });
  scored.sort((a, b) => b.score - a.score);
  return scored[0].agent;
}

workerPlans = workerPlans.map(plan => {
  const match = matchAgent(plan.task, state.availableAgents);
  if (match && (!plan.agentName || !plan.agentUrl)) {
    return { ...plan, agentName: plan.agentName || match.name, agentUrl: plan.agentUrl || match.url };
  }
  return plan;
});

const fallbackAgents = state.availableAgents || [];
workerPlans = workerPlans.map(plan => ({
  name: plan.name,
  role: plan.role,
  task: plan.task,
  agentName: plan.agentName || (fallbackAgents.length > 0 ? fallbackAgents[0].name : ''),
  agentUrl: plan.agentUrl || (fallbackAgents.length > 0 ? fallbackAgents[0].url : '')
}));

console.log(`[planner] Defined ${workerPlans.length} workers:`, JSON.stringify(workerPlans, null, 2));
return { workerPlans, messages: [response] };

const plan = state.currentPlan;
if (!plan || !plan.agentUrl) {
  console.warn('[worker] No currentPlan or agentUrl, skipping');
  return { workerResults: [{ name: plan?.name || 'unknown', result: 'No plan or agentUrl found' }] };
}
console.log(`[worker:${plan.name}] Connecting to ${plan.agentUrl}`);

const tool = await __registerA2AAgent(plan.name, {
  cardUrl: `${plan.agentUrl}/.well-known/agent.json`,
  timeout: 5000
});

let result;
if (tool) {
  console.log(`[worker:${plan.name}] Sending task via A2A tool`);
  result = await tool.invoke(plan.task);
} else {
  result = `Error: Failed to connect to agent at ${plan.agentUrl}`;
}

console.log(`[worker:${plan.name}] Completed`);
return { workerResults: [{ name: plan.name, result: String(result) }] };

console.log(`[aggregator] Aggregating ${state.workerResults.length} worker results`);

const resultsSummary = state.workerResults.map(r => `## ${r.name}\n${r.result}`).join('\n\n');

const aggregatePrompt = `The following are the research and work results from each specialist team.

${resultsSummary}

Integrate these results to create a comprehensive final report in English.
Combine the contributions of each team member appropriately and organize the response to address the user's original request.`;

let finalReport = '';
for (let attempt = 0; attempt < 3; attempt++) {
  const response = await model.invoke([{ role: 'user', content: aggregatePrompt }]);
  const content = typeof response.content === 'string' ? response.content : JSON.stringify(response.content);
  if (content && content.trim()) {
    finalReport = content;
    break;
  }
  console.warn(`[aggregator] Empty response on attempt ${attempt + 1}, retrying...`);
}

if (!finalReport) {
  console.warn('[aggregator] All attempts returned empty, falling back to worker results summary');
  finalReport = state.workerResults.map(r => `## ${r.name}\n${r.result || '(no result)'}`).join('\n\n');
}

console.log('[aggregator] Final report generated, length:', finalReport.length);
return { finalReport, messages: [{ role: 'assistant', content: finalReport }] };

console.log('[finalize] Swarms workflow complete');
const report = (state.finalReport && state.finalReport.trim()) ? state.finalReport : (state.messages.slice().reverse().find(m => m.role === 'assistant' && m.content && m.content.trim())?.content) || 'No report generated';
return { messages: [{ role: 'assistant', content: report }] };
